1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
17	//
18	//	{"version":1,
19	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
20	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
21	//	 "settlements":[{...一笔成功结算及其当时费率...}],
22	//	 "refunds":[{...一笔成功全额退款...}],
23	//	 "checksum":"<sha256 of the document without checksum>"}
24	//
25	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
26	// checksum 覆盖截断、比特翻转与所有语义编辑。
27	//
28	// refunds 字段缺省（旧版账本没有该字段）即视为空列表：旧文件可直接打开；
29	// 只要账本没有发生退款，写回时该字段继续缺省，读取旧账本不会改写文件。
30	//
31	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
32	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
33	// 不会出现“扣款/退款无记录”或“记录未改余额”的中间状态。
34	const ledgerVersion = 1
35	
36	// 结算结果状态，与命令行输出一一对应，可分别识别。
37	const (
38		StatusSettled         = "settled"              // 成功扣款
39		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
40		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
41		StatusState           = "state_error"          // 非 pending
42		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
43		StatusLimitExceeded   = "limit_exceeded"       // 本次批次该 (账户, 资产) 组合的扣款上限不足
44		StatusInvalid         = "invalid_parameter"
45		StatusStorage         = "storage_error"
46		StatusRefundSuccess   = "refunded"         // 成功全额退回
47		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
48		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
49	)
50	
51	// 拒绝原因。
52	const (
53		reasonEmptyID         = "intent id must not be empty"
54		reasonEmptyAccount    = "account must not be empty"
55		reasonEmptyAsset      = "asset must not be empty"
56		reasonBadAmount       = "amount must be a positive int64"
57		reasonOverflow        = "amount plus fee overflows int64"
58		reasonNotPending      = "intent is not pending"
59		reasonFunds           = "insufficient balance for amount plus fee"
60		reasonLimitExceeded   = "charge limit exceeded for %s/%s: max_charged %d, used %d, this item charges %d"
61		reasonDuplicate       = "duplicate settlement attempt"
62		reasonConflict        = "settlement id conflicts with a different request"
63		reasonEmptyRefundID   = "refund id must not be empty"
64		reasonEmptySettlement = "settlement_id must not be empty"
65		reasonEmptyReason     = "refund reason must not be empty"
66		reasonSettlementGone  = "settlement %q not found"
67		reasonAlreadyRefunded = "settlement %q has already been refunded by %q"
68		reasonRefundConflict  = "refund id conflicts with a different request"
69		reasonDuplicateRefund = "duplicate refund attempt"
70	)
71	
72	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
73	type BalanceInit struct {
74		Account string `json:"account"`
75		Asset   string `json:"asset"`
76		Balance int64  `json:"balance"`
77	}
78	
79	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
80	type PaymentIntent struct {
81		ID        string `json:"id"`
82		Account   string `json:"account"`
83		Paymaster string `json:"paymaster"`
84		Asset     string `json:"asset"`
85		Amount    *int64 `json:"amount"`
86		Nonce     uint64 `json:"nonce"`
87		State     string `json:"state"`
88	}
89	
90	// ChargeLimit 是本次提交中一个 (账户, 资产) 组合的扣款上限：该组合在本批次内
91	// 成功落账的 charged（付款金额 + 手续费）累计不得超过 max_charged。
92	// 上限仅对本次提交有效，不持久化；历史扣款与退款都不占本次额度。
93	// MaxCharged 使用指针以区分“缺省/null”与显式给出的 0（0 表示禁止该组合新增扣款）。
94	type ChargeLimit struct {
95		Account    string `json:"account"`
96		Asset      string `json:"asset"`
97		MaxCharged *int64 `json:"max_charged"`
98	}
99	
100	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表 + 可选的本次扣款上限。
101	// Limits 缺省、为 null 或为空数组时不限制扣款。
102	type FeeBatch struct {
103		FeeBps  int             `json:"fee_bps"`
104		Intents []PaymentIntent `json:"intents"`
105		Limits  []ChargeLimit   `json:"limits,omitempty"`
106	}
107	
108	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
109	type Record struct {
110		ID        string `json:"id"`
111		Account   string `json:"account"`
112		Paymaster string `json:"paymaster"`
113		Asset     string `json:"asset"`
114		Amount    int64  `json:"amount"`
115		Nonce     uint64 `json:"nonce"`
116		FeeBps    int    `json:"fee_bps"`
117		Fee       int64  `json:"fee"`
118		Charged   int64  `json:"charged"`
119		Seq       int64  `json:"seq"`
120	}
121	
122	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
123	type ItemResult struct {
124		ID     string  `json:"id"`
125		Status string  `json:"status"`
126		Reason string  `json:"reason,omitempty"`
127		Record *Record `json:"record,omitempty"`
128	}
129	
130	// BatchResult 是一次提交的结果。空批次对应空 Results。
131	type BatchResult struct {
132		Results []ItemResult `json:"results"`
133	}
134	
135	// PreviewResult 是一次提交预览（--dry-run）的结果。DryRun 恒为 true，
136	// 用于与真实提交输出区分；Results 与输入逐项对应，状态、失败原因与结算
137	// 记录格式与 Submit 完全一致——其中 settled 表示“按当前账本预计能够成功”，
138	// 携带的记录使用从当前最大付款序号之后连续递增的预计序号。
139	// 预览不写入账本，序号、余额与本批次额度都不会被预留。
140	type PreviewResult struct {
141		DryRun  bool         `json:"dry_run"`
142		Results []ItemResult `json:"results"`
143	}
144	
145	// RefundRequest 是退款批次中的一项：退款编号、原付款编号、退款原因，三者均须非空。
146	type RefundRequest struct {
147		ID           string `json:"id"`
148		SettlementID string `json:"settlement_id"`
149		Reason       string `json:"reason"`
150	}
151	
152	// RefundBatch 是一次退款提交：有序的退款请求列表。
153	type RefundBatch struct {
154		Refunds []RefundRequest `json:"refunds"`
155	}
156	
157	// RefundRecord 是一笔成功全额退款留下的永久记录，按退款成功先后顺序保存。
158	// 退款金额与去向（账户/资产/总额）全部由原结算记录确定，因此一并冗余记录，
159	// 使每条退款都能脱离上下文自解释、可追溯原结算。
160	// AfterSeq 是退款落账时结算历史的长度：余额校验要求该结算在此时点之前发生。
161	type RefundRecord struct {
162		ID           string `json:"id"`
163		SettlementID string `json:"settlement_id"`
164		Reason       string `json:"reason"`
165		Account      string `json:"account"`
166		Asset        string `json:"asset"`
167		Amount       int64  `json:"amount"`
168		Fee          int64  `json:"fee"`
169		Charged      int64  `json:"charged"`
170		AfterSeq     int64  `json:"after_seq"`
171		Seq          int64  `json:"seq"`
172	}
173	
174	// RefundResult 是一项退款的处理结果。成功与幂等重复携带原付款编号、账户、
175	// 资产、退款总额与原因；失败只带状态与说明。
176	type RefundResult struct {
177		ID           string        `json:"id"`
178		Status       string        `json:"status"`
179		Reason       string        `json:"reason,omitempty"`
180		SettlementID string        `json:"settlement_id,omitempty"`
181		Account      string        `json:"account,omitempty"`
182		Asset        string        `json:"asset,omitempty"`
183		Charged      int64         `json:"charged,omitempty"`
184		Record       *RefundRecord `json:"record,omitempty"`
185	}
186	
187	// RefundBatchResult 是一次退款提交的结果，顺序与输入逐项对应。
188	type RefundBatchResult struct {
189		Results []RefundResult `json:"results"`
190	}
191	
192	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
193	type BalanceView struct {
194		Account string `json:"account"`
195		Asset   string `json:"asset"`
196		Balance int64  `json:"balance"`
197	}
198	
199	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
200	type Snapshot struct {
201		Balances    []BalanceView  `json:"balances"`
202		Settlements []Record       `json:"settlements"`
203		Refunds     []RefundRecord `json:"refunds"`
204	}
205	
206	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
207	type LedgerError struct {
208		Kind    string
209		Message string
210	}
211	
212	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
213	
214	// 错误分类。
215	const (
216		ErrInvalid = "invalid_parameter"
217		ErrExists  = "ledger_exists"
218		ErrCorrupt = "corrupt_ledger"
219		ErrStorage = "storage_error"
220		ErrClosed  = "ledger_closed"
221		ErrNotInit = "ledger_not_initialized"
222	)
223	
224	func ledgerError(kind, format string, args ...any) error {
225		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
226	}
227	
228	// KindOf 返回错误的分类；非账本错误按存储错误处理。
229	func KindOf(err error) string {
230		var le *LedgerError
231		if errors.As(err, &le) {
232			return le.Kind
233		}
234		return ErrStorage
235	}
236	
237	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
238	// 内存状态必须回滚到该项执行之前。仅用于测试。
239	type FailWriter interface {
240		FailNextPersist() bool
241	}
242	
243	type balanceKey struct {
244		account string
245		asset   string
246	}
247	
248	type ledgerState struct {
249		Version     int
250		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
251		Balances    map[balanceKey]int64 // 当前余额
252		Settlements []Record
253		Refunds     []RefundRecord
254	}
255	
256	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
257	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
258	// 且无退款的账本写回时继续省略该字段。
259	type unsignedDoc struct {
260		Version     int            `json:"version"`
261		Initial     []BalanceView  `json:"initial_balances"`
262		Balances    []BalanceView  `json:"balances"`
263		Settlements []Record       `json:"settlements"`
264		Refunds     []RefundRecord `json:"refunds,omitempty"`
265	}
266	
267	type signedDoc struct {
268		unsignedDoc
269		Checksum string `json:"checksum"`
270	}
271	
272	func balanceList(m map[balanceKey]int64) []BalanceView {
273		out := make([]BalanceView, 0, len(m))
274		for k, v := range m {
275			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
276		}
277		sortBalances(out)
278		return out
279	}
280	
281	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
282		out := make(map[balanceKey]int64, len(list))
283		for i, b := range list {
284			if b.Account == "" || b.Asset == "" {
285				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
286			}
287			if b.Balance < 0 {
288				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
289			}
290			k := balanceKey{b.Account, b.Asset}
291			if _, dup := out[k]; dup {
292				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
293			}
294			out[k] = b.Balance
295		}
296		return out, nil
297	}
298	
299	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
300	func (s *ledgerState) MarshalJSON() ([]byte, error) {
301		settlements := s.Settlements
302		if settlements == nil {
303			settlements = []Record{}
304		}
305		doc := unsignedDoc{
306			Version:     s.Version,
307			Initial:     balanceList(s.Initial),
308			Balances:    balanceList(s.Balances),
309			Settlements: settlements,
310			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
311		}
312		payload, err := json.Marshal(doc)
313		if err != nil {
314			return nil, err
315		}
316		sum := checksumHex(payload)
317		out := make([]byte, 0, len(payload)+len(sum)+16)
318		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
319		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
320		return out, nil
321	}
322	
323	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
324	func (s *ledgerState) UnmarshalJSON(data []byte) error {
325		var doc signedDoc
326		if err := json.Unmarshal(data, &doc); err != nil {
327			return err
328		}
329		if doc.Checksum == "" {
330			return ledgerError(ErrCorrupt, "missing checksum")
331		}
332		payload, err := json.Marshal(doc.unsignedDoc)
333		if err != nil {
334			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
335		}
336		if got := checksumHex(payload); got != doc.Checksum {
337			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
338		}
339		if doc.Version != ledgerVersion {
340			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
341		}
342		initial, err := balanceMap(doc.Initial)
343		if err != nil {
344			return err
345		}
346		current, err := balanceMap(doc.Balances)
347		if err != nil {
348			return err
349		}
350		records := doc.Settlements
351		if records == nil {
352			records = []Record{}
353		}
354		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
355		if refunds == nil {
356			refunds = []RefundRecord{}
357		}
358		if err := validateAndReplay(initial, current, records, refunds); err != nil {
359			return err
360		}
361		s.Version = doc.Version
362		s.Initial = initial
363		s.Balances = current
364		s.Settlements = records
365		s.Refunds = refunds
366		return nil
367	}
368	
369	func decodeState(data []byte) (*ledgerState, error) {
370		var state ledgerState
371		if err := json.Unmarshal(data, &state); err != nil {
372			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
373				return nil, err
374			}
375			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
376		}
377		return &state, nil
378	}
379	
380	// canonicalLedgerPath 把绝对路径解析为账本的规范路径：解析目录与文件本身
381	// 的符号链接，使同一账本经不同路径（如指向账本所在目录的软链接）打开时
382	// 共享同一注册表项、同一份内存状态与互斥锁。账本文件尚不存在时（未初始化）
383	// 解析其父目录；父目录也无法解析时退回原路径。
384	func canonicalLedgerPath(abs string) string {
385		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
386			return resolved
387		}
388		if resolved, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
389			return filepath.Join(resolved, filepath.Base(abs))
390		}
391		return abs
392	}
393	
394	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
395	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
396	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
397	func CreateLedger(path string, init []BalanceInit) error {
398		if err := validateInitial(init); err != nil {
399			return err
400		}
401		abs, err := filepath.Abs(path)
402		if err != nil {
403			return ledgerError(ErrStorage, "resolve path: %v", err)
404		}
405		abs = canonicalLedgerPath(abs)
406	
407		openMu.Lock()
408		defer openMu.Unlock()
409	
410		if _, err := os.Stat(abs); err == nil {
411			return ledgerError(ErrExists, "ledger already exists at %s", abs)
412		} else if !errors.Is(err, os.ErrNotExist) {
413			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
414		}
415		// 已有句柄打开（或有在途操作）的路径不能再初始化：即便文件恰好被外部
416		// 删除，也不能用一本新账顶替正在使用的账本。无活动句柄时不做拦截——
417		// 是否已初始化完全由上面的磁盘检查决定。
418		if openRegistry[abs] != nil {
419			return ledgerError(ErrExists, "ledger is already initialized in this process")
420		}
421	
422		// 文件存在即视为已初始化：CreateLedger 不预登记内存状态，账本是否存在、
423		// 内容是否完好一律以磁盘为准，首次 Open 必须实际读取并校验该文件。
424		state := &ledgerState{
425			Version:     ledgerVersion,
426			Initial:     make(map[balanceKey]int64, len(init)),
427			Balances:    make(map[balanceKey]int64, len(init)),
428			Settlements: []Record{},
429			Refunds:     []RefundRecord{},
430		}
431		for _, b := range init {
432			k := balanceKey{b.Account, b.Asset}
433			state.Initial[k] = b.Balance
434			state.Balances[k] = b.Balance
435		}
436		if err := atomicWrite(abs, state); err != nil {
437			return err
438		}
439		// 不登记 openRegistry：尚未有任何句柄，首次 Open 必须以磁盘文件为准，
440		// 这样在初始化与首次打开之间删除、清空或篡改文件都会被如实发现。
441		return nil
442	}
443	
444	func validateInitial(init []BalanceInit) error {
445		seen := map[balanceKey]bool{}
446		for i, b := range init {
447			if b.Account == "" {
448				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
449			}
450			if b.Asset == "" {
451				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
452			}
453			if b.Balance < 0 {
454				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
455			}
456			k := balanceKey{b.Account, b.Asset}
457			if seen[k] {
458				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
459			}
460			seen[k] = true
461		}
462		return nil
463	}
464	
465	// Ledger 是一个可持久化的本地账本。同一进程内指向同一账本文件的多次 Open
466	// （包括经目录软链接的不同路径）返回共享同一状态与互斥锁的实例，
467	// 因此并发提交按同一本账本串行化。
468	type Ledger struct {
469		path string
470		reg  *registryEntry
471		open bool
472	}
473	
474	type registryEntry struct {
475		mu       sync.Mutex // 保护 state；整个批次串行持有
476		state    *ledgerState
477		holders  map[*Ledger]struct{} // 当前打开的句柄
478		ops      int                  // 正在执行的 Submit/Query 数（含已关闭句柄的在途操作）
479		failHook FailWriter           // 仅测试注入
480	}
481	
482	// alive 报告该注册表项是否仍须保留：至少还有一个打开的句柄，或一个
483	// （可能来自已关闭句柄的）在途操作。全为零时该项可被注销，此后的 Open
484	// 重新以磁盘文件为准。
485	// 调用方必须持有 openMu。
486	func (r *registryEntry) alive() bool {
487		return len(r.holders) > 0 || r.ops > 0
488	}
489	
490	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
491	// 调用方必须持有 openMu。
492	func tryEvict(path string, reg *registryEntry) {
493		if !reg.alive() && openRegistry[path] == reg {
494			delete(openRegistry, path)
495		}
496	}
497	
498	var (
499		openMu       sync.Mutex
500		openRegistry = map[string]*registryEntry{}
501	)
502	
503	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
504	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
505	func Open(path string) (*Ledger, error) {
506		abs, err := filepath.Abs(path)
507		if err != nil {
508			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
509		}
510		abs = canonicalLedgerPath(abs)
511	
512		openMu.Lock()
513		defer openMu.Unlock()
514	
515		if reg := openRegistry[abs]; reg != nil {
516			// 同进程已有句柄（或在途操作）承接该账本：共享当前完整状态，不重新读盘。
517			// 注册表项只在存在活动句柄/在途操作期间保留，因此走到这里时磁盘文件
518			// 的状态已不再权威——例如它可能正被一笔在途付款以原子写替换。
519			h := &Ledger{path: abs, reg: reg, open: true}
520			reg.holders[h] = struct{}{}
521			return h, nil
522		}
523	
524		data, err := os.ReadFile(abs)
525		if err != nil {
526			if errors.Is(err, os.ErrNotExist) {
527				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
528			}
529			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
530		}
531		if len(bytes.TrimSpace(data)) == 0 {
532			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
533		}
534		dec := json.NewDecoder(bytes.NewReader(data))
535		var rawDoc json.RawMessage
536		if err := dec.Decode(&rawDoc); err != nil {
537			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
538		}
539		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
540		if tok, err := dec.Token(); err != io.EOF {
541			if err == nil {
542				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
543			}
544			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
545		}
546		state, err := decodeState(rawDoc)
547		if err != nil {
548			return nil, err
549		}
550	
551		reg := &registryEntry{state: state, holders: map[*Ledger]struct{}{}}
552		h := &Ledger{path: abs, reg: reg, open: true}
553		reg.holders[h] = struct{}{}
554		openRegistry[abs] = reg
555		return h, nil
556	}
557	
558	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
559	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
560	// 从磁盘重新加载而丢失正在写入的状态。
561	func (l *Ledger) Close() error {
562		openMu.Lock()
563		defer openMu.Unlock()
564		if !l.open {
565			return nil
566		}
567		l.open = false
568		delete(l.reg.holders, l)
569		tryEvict(l.path, l.reg)
570		return nil
571	}
572	
573	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
574	func (l *Ledger) beginOp() error {
575		openMu.Lock()
576		defer openMu.Unlock()
577		if !l.open {
578			return ledgerError(ErrClosed, "ledger handle is closed")
579		}
580		l.reg.ops++
581		return nil
582	}
583	
584	func (l *Ledger) endOp() {
585		openMu.Lock()
586		defer openMu.Unlock()
587		l.reg.ops--
588		tryEvict(l.path, l.reg)
589	}
590	
591	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
592	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
593	// 拆成商和余数两部分即可在 int64 内精确完成。
594	func feeFor(amount int64, feeBps int) int64 {
595		hi := amount / 10000
596		lo := amount % 10000
597		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
598	}
599	
600	func validateIntent(it PaymentIntent) (int64, string, bool) {
601		if it.ID == "" {
602			return 0, reasonEmptyID, false
603		}
604		if it.Account == "" {
605			return 0, reasonEmptyAccount, false
606		}
607		if it.Asset == "" {
608			return 0, reasonEmptyAsset, false
609		}
610		if it.Amount == nil || *it.Amount <= 0 {
611			return 0, reasonBadAmount, false
612		}
613		return *it.Amount, "", true
614	}
615	
616	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
617	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
618	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
619	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
620		if len(limits) == 0 {
621			return nil, nil
622		}
623		out := make(map[balanceKey]int64, len(limits))
624		for i, l := range limits {
625			if l.Account == "" {
626				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
627			}
628			if l.Asset == "" {
629				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
630			}
631			if l.MaxCharged == nil {
632				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
633			}
634			if *l.MaxCharged < 0 {
635				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
636			}
637			k := balanceKey{l.Account, l.Asset}
638			if _, dup := out[k]; dup {
639				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
640			}
641			out[k] = *l.MaxCharged
642		}
643		return out, nil
644	}
645	
646	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
647	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
648	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
649	//
650	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
651	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
652	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
653	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
654	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
655		if err := l.beginOp(); err != nil {
656			return nil, err
657		}
658		defer l.endOp()
659		limits, err := validateBatch(batch)
660		if err != nil {
661			return nil, err
662		}
663	
664		l.reg.mu.Lock()
665		defer l.reg.mu.Unlock()
666	
667		results := runBatch(batch, limits, l.reg.state, l.persistCharge)
668		return &BatchResult{Results: results}, nil
669	}
670	
671	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
672	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
673	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
674	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
675	//     失败、重复、冲突不消耗序号；
676	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
677	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
678	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
679	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
680	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
681	//
682	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
683	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
684	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
685	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
686	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
687	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
688		if err := l.beginOp(); err != nil {
689			return nil, err
690		}
691		defer l.endOp()
692		limits, err := validateBatch(batch)
693		if err != nil {
694			return nil, err
695		}
696	
697		l.reg.mu.Lock()
698		defer l.reg.mu.Unlock()
699	
700		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
701		sim := cloneState(l.reg.state)
702		results := runBatch(batch, limits, sim, simulateCharge)
703		return &PreviewResult{DryRun: true, Results: results}, nil
704	}
705	
706	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
707	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
708	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
709		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
710			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
711		}
712		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
713		return validateLimits(batch.Limits)
714	}
715	
716	// chargeEffect 是一笔预计成功扣款的全部账本效果：扣哪个组合、扣多少、
717	// 留下什么结算记录。它由付款规则产生，本身尚未生效；是否生效、如何生效
718	// （真实落盘或预览模拟）由生效策略决定。
719	type chargeEffect struct {
720		key    balanceKey
721		total  int64
722		record Record
723	}
724	
725	// commitCharge 是扣款生效策略：把一笔预计成功的扣款应用到状态 st 上。
726	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
727	// 该项执行之前的余额与历史。
728	type commitCharge func(st *ledgerState, eff chargeEffect) error
729	
730	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
731	// 付款规则（judgeIntent）与扣款生效（commit）分离：规则只读取 st 与
732	// 本批次已用额度给出判定和预计扣款效果，不改动任何状态；生效策略决定
733	// 效果如何落地——真实提交先改内存再原子落盘、失败回滚并报告
734	// storage_error，预览只在副本上推进内存状态、绝不落盘。两种操作共用
735	// 同一份规则，因此逐项判定完全一致。调用方必须持有 reg.mu。
736	func runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, commit commitCharge) []ItemResult {
737		out := make([]ItemResult, 0, len(batch.Intents))
738	
739		// 本次批次内各组合已消耗的额度，从零开始，仅成功生效的扣款计入。
740		used := make(map[balanceKey]int64, len(limits))
741	
742		for i := range batch.Intents {
743			it := &batch.Intents[i]
744	
745			// 1. 规则判定：纯读取，不产生任何副作用。
746			res, charge := judgeIntent(it, batch.FeeBps, limits, used, st)
747			if charge == nil {
748				out = append(out, res)
749				continue
750			}
751	
752			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
753			//    该项报告 storage_error，不留记录、不占额度，后项继续处理。
754			if err := commit(st, *charge); err != nil {
755				res.Status = StatusStorage
756				res.Reason = err.Error()
757				out = append(out, res)
758				continue
759			}
760	
761			// 3. 只有成功生效的扣款才消耗本批次额度（预览同样如此）。
762			used[charge.key] += charge.total
763			cp := charge.record
764			res.Status = StatusSettled
765			res.Record = &cp
766			out = append(out, res)
767		}
768		return out
769	}
770	
771	// judgeIntent 按付款规则评估一项请求，只读取状态与额度用量，不产生副作用。
772	// 返回逐项结果；预计成功时结果只填编号，扣款效果以 chargeEffect 描述，
773	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功编号的
774	// 重复/冲突、状态、溢出、本批次限额（先于余额）、余额。
775	func judgeIntent(it *PaymentIntent, feeBps int, limits map[balanceKey]int64, used map[balanceKey]int64, st *ledgerState) (ItemResult, *chargeEffect) {
776		res := ItemResult{ID: it.ID}
777	
778		// 1. 参数校验。未通过的编号不占用去重资格。
779		amount, reason, ok := validateIntent(*it)
780		if !ok {
781			res.Status = StatusInvalid
782			res.Reason = reason
783			return res, nil
784		}
785	
786		// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
787		//    任一不同则编号冲突。两者都不再扣款、不改原记录。
788		//    本批次内先（预计）成功的同编号项也在此被看到。
789		if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
790			if sameRequest(rec, it, amount, feeBps) {
791				cp := rec
792				res.Status = StatusDuplicate
793				res.Reason = reasonDuplicate
794				res.Record = &cp
795			} else {
796				res.Status = StatusConflict
797				res.Reason = reasonConflict
798			}
799			return res, nil
800		}
801	
802		// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
803		if it.State != "" && it.State != "pending" {
804			res.Status = StatusState
805			res.Reason = reasonNotPending
806			return res, nil
807		}
808	
809		// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
810		fee := feeFor(amount, feeBps)
811		if fee > math.MaxInt64-amount {
812			res.Status = StatusInvalid
813			res.Reason = reasonOverflow
814			return res, nil
815		}
816		total := amount + fee
817	
818		key := balanceKey{it.Account, it.Asset}
819	
820		// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
821		//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
822		//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
823		if max, capped := limits[key]; capped {
824			if u := used[key]; total > max-u {
825				res.Status = StatusLimitExceeded
826				res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
827				return res, nil
828			}
829		}
830	
831		// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
832		if total > st.Balances[key] {
833			res.Status = StatusFunds
834			res.Reason = reasonFunds
835			return res, nil
836		}
837	
838		// 7. 预计成功：描述扣款效果（序号按当前历史长度连续递增）。
839		return res, &chargeEffect{
840			key:   key,
841			total: total,
842			record: Record{
843				ID:        it.ID,
844				Account:   it.Account,
845				Paymaster: it.Paymaster,
846				Asset:     it.Asset,
847				Amount:    amount,
848				Nonce:     it.Nonce,
849				FeeBps:    feeBps,
850				Fee:       fee,
851				Charged:   total,
852				Seq:       int64(len(st.Settlements)) + 1,
853			},
854		}
855	}
856	
857	// simulateCharge 是预览的生效策略：只在（副本）状态上推进余额与历史，
858	// 绝不触碰磁盘，因此不会失败，预览结果中也不会出现 storage_error。
859	func simulateCharge(st *ledgerState, eff chargeEffect) error {
860		st.Balances[eff.key] -= eff.total
861		st.Settlements = append(st.Settlements, eff.record)
862		return nil
863	}
864	
865	// persistCharge 是真实提交的生效策略：先在内存生效，再原子落盘；
866	// 落盘失败回滚该项（恢复余额与历史），并返回存储错误。
867	func (l *Ledger) persistCharge(st *ledgerState, eff chargeEffect) error {
868		rollback := stageOn(st, eff.key, st.Balances[eff.key]-eff.total, eff.record)
869		if err := l.persistLocked(); err != nil {
870			rollback()
871			return err
872		}
873		return nil
874	}
875	
876	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
877	func cloneState(st *ledgerState) *ledgerState {
878		cp := &ledgerState{
879			Version:     st.Version,
880			Initial:     make(map[balanceKey]int64, len(st.Initial)),
881			Balances:    make(map[balanceKey]int64, len(st.Balances)),
882			Settlements: append([]Record(nil), st.Settlements...),
883			Refunds:     append([]RefundRecord(nil), st.Refunds...),
884		}
885		for k, v := range st.Initial {
886			cp.Initial[k] = v
887		}
888		for k, v := range st.Balances {
889			cp.Balances[k] = v
890		}
891		return cp
892	}
893	
894	// findRecordIn 在给定结算历史中按编号查找成功记录。
895	func findRecordIn(records []Record, id string) (Record, bool) {
896		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
897		for _, r := range records {
898			if r.ID == id {
899				return r, true
900			}
901		}
902		return Record{}, false
903	}
904	
905	// stageOn 在指定状态上应用一笔扣款与记录，返回回滚函数（恢复该项执行前的
906	// 余额与记录长度）。
907	func stageOn(st *ledgerState, key balanceKey, newBal int64, rec Record) func() {
908		oldBal, hadKey := st.Balances[key]
909		oldLen := len(st.Settlements)
910		st.Balances[key] = newBal
911		st.Settlements = append(st.Settlements, rec)
912		return func() {
913			if hadKey {
914				st.Balances[key] = oldBal
915			} else {
916				delete(st.Balances, key)
917			}
918			st.Settlements = st.Settlements[:oldLen]
919		}
920	}
921	
922	// validateRefundRequest 校验一项退款请求：退款编号、原付款编号、原因三者
923	// 都必须非空，校验顺序即对外约定（id → settlement_id → reason）。
924	// 未通过校验的编号不占用退款资格，之后可修改后重新提交。
925	func validateRefundRequest(req *RefundRequest) (string, bool) {
926		if req.ID == "" {
927			return reasonEmptyRefundID, false
928		}
929		if req.SettlementID == "" {
930			return reasonEmptySettlement, false
931		}
932		if req.Reason == "" {
933			return reasonEmptyReason, false
934		}
935		return "", true
936	}
937	
938	// refundEffect 是一笔预计成功退款的全部账本效果：退回哪个组合、退回多少、
939	// 留下什么退款记录。它由退款规则产生，本身尚未生效；是否生效、如何生效
940	// （真实落盘，失败则回滚）由生效策略决定。
941	type refundEffect struct {
942		key    balanceKey
943		amount int64
944		record RefundRecord
945	}
946	
947	// attachRefundDetail 把一笔成功退款（首次成功或幂等重复携带的同一条原记录）
948	// 的统一详情填入逐项结果：原付款编号、账户、资产、退款总额、原因与完整退款
949	// 记录。首次成功与重复申请共用这一个出口，保证两者拼装出的详情逐字一致。
950	func attachRefundDetail(res *RefundResult, rec RefundRecord) {
951		res.Reason = rec.Reason
952		res.SettlementID = rec.SettlementID
953		res.Account = rec.Account
954		res.Asset = rec.Asset
955		res.Charged = rec.Charged
956		cp := rec
957		res.Record = &cp
958	}
959	
960	// judgeRefund 按退款规则评估一项请求，只读取状态 st，不产生任何副作用。
961	// 返回逐项结果；预计成功时结果只填编号，退款效果以 refundEffect 描述，
962	// 由调用方交给生效策略落地。判定顺序即对外约定：参数校验、已成功退款编号
963	// 的重复/冲突（优先于目标判断，即使新目标不存在也不退化成 not_found）、
964	// 目标结算存在性、目标是否已被其他退款编号退回。
965	func judgeRefund(req *RefundRequest, st *ledgerState) (RefundResult, *refundEffect) {
966		res := RefundResult{ID: req.ID}
967	
968		// 1. 参数校验。未通过的编号不占用退款资格。
969		if reason, ok := validateRefundRequest(req); !ok {
970			res.Status = StatusInvalid
971			res.Reason = reason
972			return res, nil
973		}
974	
975		// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
976		//    任一不同则冲突（即使新目标不存在也不能退化成 not_found）。
977		//    两者都不再入账。本批次内先成功的同编号项也在此被看到。
978		if prior, exists := findRefundIn(st.Refunds, req.ID); exists {
979			if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
980				res.Status = StatusDuplicate
981				attachRefundDetail(&res, prior)
982			} else {
983				res.Status = StatusConflict
984				res.Reason = reasonRefundConflict
985			}
986			return res, nil
987		}
988	
989		// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
990		target, exists := findRecordIn(st.Settlements, req.SettlementID)
991		if !exists {
992			res.Status = StatusNotFound
993			res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
994			return res, nil
995		}
996	
997		// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
998		if prior, refunded := findRefundOfSettlementIn(st.Refunds, req.SettlementID); refunded {
999			res.Status = StatusAlreadyRefunded
1000			res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
1001			return res, nil
1002		}
1003	
1004		// 5. 预计成功：全额（amount 与当时手续费一并，即以原结算的 charged 为准）
1005		//    退回原账户、原资产；序号按当前退款历史长度连续递增。
1006		rec := RefundRecord{
1007			ID:           req.ID,
1008			SettlementID: target.ID,
1009			Reason:       req.Reason,
1010			Account:      target.Account,
1011			Asset:        target.Asset,
1012			Amount:       target.Amount,
1013			Fee:          target.Fee,
1014			Charged:      target.Charged,
1015			AfterSeq:     int64(len(st.Settlements)),
1016			Seq:          int64(len(st.Refunds)) + 1,
1017		}
1018		return res, &refundEffect{
1019			key:    balanceKey{target.Account, target.Asset},
1020			amount: target.Charged,
1021			record: rec,
1022		}
1023	}
1024	
1025	// commitRefund 是退款生效策略：把一笔预计成功的退款应用到状态 st 上。
1026	// 返回 nil 表示已生效；返回非 nil 表示保存失败，且 st 必须已恢复到
1027	// 该项执行之前的余额与退款历史。
1028	type commitRefund func(st *ledgerState, eff refundEffect) error
1029	
1030	// runRefundBatch 按输入顺序在给定状态 st 上处理整个退款批次，返回逐项结果。
1031	// 退款规则（judgeRefund）与生效（commit）分离：规则只读取 st 给出判定和
1032	// 预计退款效果，不改动任何状态；生效策略决定效果如何落地——真实提交先改
1033	// 内存再原子落盘、失败回滚并报告 storage_error。保存失败时 commit 已回滚
1034	// 该项（余额与退款历史恢复原样），该项不占退款编号、不把原付款标成已退款，
1035	// 前项成功保留、后项继续处理。调用方必须持有 reg.mu。
1036	func runRefundBatch(batch RefundBatch, st *ledgerState, commit commitRefund) []RefundResult {
1037		out := make([]RefundResult, 0, len(batch.Refunds))
1038		for i := range batch.Refunds {
1039			req := &batch.Refunds[i]
1040	
1041			// 1. 规则判定：纯读取，不产生任何副作用。
1042			res, eff := judgeRefund(req, st)
1043			if eff == nil {
1044				out = append(out, res)
1045				continue
1046			}
1047	
1048			// 2. 生效：保存失败时 commit 已回滚该项（余额与历史恢复原样），
1049			//    该项报告 storage_error，不留退款记录、不占退款序号，后项继续。
1050			if err := commit(st, *eff); err != nil {
1051				res.Status = StatusStorage
1052				res.Reason = err.Error()
1053				out = append(out, res)
1054				continue
1055			}
1056	
1057			// 3. 成功落账：与重复申请一样通过统一出口拼装详情。
1058			res.Status = StatusRefundSuccess
1059			attachRefundDetail(&res, eff.record)
1060			out = append(out, res)
1061		}
1062		return out
1063	}
1064	
1065	// persistRefund 是真实退款的生效策略：先在内存生效，再原子落盘；
1066	// 落盘失败回滚该项（恢复余额与退款历史），并返回存储错误。
1067	func (l *Ledger) persistRefund(st *ledgerState, eff refundEffect) error {
1068		rollback := stageRefundOn(st, eff.key, st.Balances[eff.key]+eff.amount, eff.record)
1069		if err := l.persistLocked(); err != nil {
1070			rollback()
1071			return err
1072		}
1073		return nil
1074	}
1075	
1076	// stageRefundOn 在指定状态上应用一笔退款（余额增加 + 退款记录追加），
1077	// 返回回滚函数（恢复该项执行前的余额与退款记录长度）。
1078	func stageRefundOn(st *ledgerState, key balanceKey, newBal int64, rec RefundRecord) func() {
1079		oldBal, hadKey := st.Balances[key]
1080		oldLen := len(st.Refunds)
1081		st.Balances[key] = newBal
1082		st.Refunds = append(st.Refunds, rec)
1083		return func() {
1084			if hadKey {
1085				st.Balances[key] = oldBal
1086			} else {
1087				delete(st.Balances, key)
1088			}
1089			st.Refunds = st.Refunds[:oldLen]
1090		}
1091	}
1092	
1093	// findRefundIn 在给定退款历史中按编号查找成功记录。
1094	func findRefundIn(refunds []RefundRecord, id string) (RefundRecord, bool) {
1095		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1096		for _, r := range refunds {
1097			if r.ID == id {
1098				return r, true
1099			}
1100		}
1101		return RefundRecord{}, false
1102	}
1103	
1104	// findRefundOfSettlementIn 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1105	func findRefundOfSettlementIn(refunds []RefundRecord, settlementID string) (RefundRecord, bool) {
1106		for _, r := range refunds {
1107			if r.SettlementID == settlementID {
1108				return r, true
1109			}
1110		}
1111		return RefundRecord{}, false
1112	}
1113	
1114	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
1115	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
1116	// 结果与输入逐项对应，空批次返回空结果。
1117	//
1118	// 语义：
1119	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
1120	//     及原退款记录（不再入账）；任一不同返回 conflict（即使新目标不存在也一样，
1121	//     不能退化成 not_found）。
1122	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
1123	//     该结算已被其他退款编号退回返回 already_refunded，不增加余额。
1124	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
1125	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
1126	//   - 失败申请（参数错误、目标不存在、已退款、冲突、存储错误）不占用退款编号，
1127	//     之后可修改原因或目标再提交。
1128	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
1129		if err := l.beginOp(); err != nil {
1130			return nil, err
1131		}
1132		defer l.endOp()
1133	
1134		l.reg.mu.Lock()
1135		defer l.reg.mu.Unlock()
1136	
1137		results := runRefundBatch(batch, l.reg.state, l.persistRefund)
1138		return &RefundBatchResult{Results: results}, nil
1139	}
1140	
1141	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1142	
1143	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1144	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1145		return r.Account == it.Account &&
1146			r.Paymaster == it.Paymaster &&
1147			r.Asset == it.Asset &&
1148			r.Amount == amount &&
1149			r.Nonce == it.Nonce &&
1150			r.FeeBps == feeBps
1151	}
1152	
1153	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1154	func (l *Ledger) Query() (*Snapshot, error) {
1155		if err := l.beginOp(); err != nil {
1156			return nil, err
1157		}
1158		defer l.endOp()
1159		l.reg.mu.Lock()
1160		defer l.reg.mu.Unlock()
1161	
1162		st := l.stateView()
1163		bals := make([]BalanceView, 0, len(st.Balances))
1164		for k, v := range st.Balances {
1165			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1166		}
1167		sortBalances(bals)
1168		recs := make([]Record, len(st.Settlements))
1169		copy(recs, st.Settlements)
1170		refunds := make([]RefundRecord, len(st.Refunds))
1171		copy(refunds, st.Refunds)
1172		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1173	}
1174	
1175	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1176	func (l *Ledger) Balance(account, asset string) (int64, error) {
1177		if err := l.beginOp(); err != nil {
1178			return 0, err
1179		}
1180		defer l.endOp()
1181		l.reg.mu.Lock()
1182		defer l.reg.mu.Unlock()
1183		return l.stateView().Balances[balanceKey{account, asset}], nil
1184	}
1185	
1186	func sortBalances(bals []BalanceView) {
1187		sort.Slice(bals, func(i, j int) bool {
1188			if bals[i].Account != bals[j].Account {
1189				return bals[i].Account < bals[j].Account
1190			}
1191			return bals[i].Asset < bals[j].Asset
1192		})
1193	}
1194	
1195	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1196	func (l *Ledger) persistLocked() error {
1197		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1198			return ledgerError(ErrStorage, "injected write failure")
1199		}
1200		return atomicWrite(l.path, l.stateView())
1201	}
1202	
1203	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1204	func SetFailHook(l *Ledger, fw FailWriter) {
1205		l.reg.failHook = fw
1206	}
1207

